label("$b$", interp(B,P,0.2), NW, red);
label("$c$", interp(C,P,0.2), W, red);
label("$d$", interp(D,P,0.2), E, red);
label("$\alpha$", P + (-0.25,-0.35), UnFill);
label("$\beta$", P + (-0.05,-0.65), UnFill);
label("$\gamma$", P + (-0.35,-0.7), UnFill);
